from pathlib import Pathimport pandas as pdimport numpy as npPROJECT_ROOT = Path(__file__).resolve().parent.parentRESULTS_DIR = PROJECT_ROOT / "results"input_file = RESULTS_DIR / "multisat_2024_classification.csv"output_file = RESULTS_DIR / "multisat_2024_mission_screening.csv"df = pd.read_csv(input_file)# Get launch year from international designator,# e.g. 1960-007A -> 1960df["launch_year"] = pd.to_numeric(    df["INTLDES"].astype("string").str.extract(        r"^(\d{4})-"    )[0],    errors="coerce")# Approximate spacecraft age at the 2024 eventdf["age_at_storm_years"] = 2024 - df["launch_year"]# Group by launch eradf["launch_era"] = pd.cut(    df["launch_year"],    bins=[1950, 1980, 2000, 2015, 2020, 2024],    labels=[        "1951-1980",        "1981-2000",        "2001-2015",        "2016-2020",        "2021-2024",    ],    include_lowest=True)# Historical age does NOT establish mission statusdf["operational_status"] = "Unverified"# Have not verified maneuver capability df["station_keeping_capability"] = "Unverified"print("\nSATELLITES BY LAUNCH ERA:")print(    df["launch_era"]    .value_counts(dropna=False)    .sort_index()    .to_string())print("\nSATELLITES BY ALTITUDE AND LAUNCH ERA:")print(    pd.crosstab(        df["altitude_band"],        df["launch_era"]    ).to_string())# Identify recently launched candidates for# future verification, not confirmed active satellitesrecent = df[df["launch_year"] >= 2020].copy()print("\nRECENTLY LAUNCHED CANDIDATES:")print(    recent[        [            "norad_id",            "satellite_name",            "launch_year",            "reference_altitude_km",            "altitude_band"        ]    ].to_string(index=False))df.to_csv(output_file, index=False)print(f"\nSaved: {output_file}")print(f"Total spacecraft: {len(df)}")print(f"Launched 2020 or later: {len(recent)}")